implementation:
AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags) {
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_UI16  name_length;
    AP4_String  handler_name;

    // Read pre-defined values
    stream.ReadUI32(pre_defined[0]);
    stream.ReadUI32(pre_defined[1]);
    stream.ReadUI32(pre_defined[2]);

    // Read handler type
    stream.ReadUI32(handler_type);

    // Read reserved fields
    stream.ReadUI32(reserved[0]);
    stream.ReadUI32(reserved[1]);

    // Determine name length based on atom size
    AP4_UI32 remaining = size - (stream.Tell() - stream.GetStart());

    if (remaining >= 2) {
        // Read name length (Pascal-style string)
        stream.ReadUI16(name_length);
        remaining -= 2;

        if (name_length > 0 && remaining >= name_length) {
            // Read handler name (Pascal-style string)
            AP4_UI08* name_data = new AP4_UI08[name_length + 1];
            stream.Read(name_data, name_length);
            name_data[name_length] = 0; // null-terminate
            handler_name = AP4_String(reinterpret_cast<char*>(name_data));
            delete[] name_data;
        } else if (name_length == 0 && remaining >= 1) {
            // Read handler name (C-style string)
            AP4_UI08 name_char;
            stream.ReadUI08(name_char);
            handler_name = AP4_String(reinterpret_cast<char*>(&name_char));
        }
    } else {
        // No name available
        handler_name = "";
    }

    // Set handler name
    m_HandlerName = handler_name;
}
